const LIMITS = { critical: 1.0, normal: 0.8, low: 0.5 } // share of capacity
app.use((req, res, next) => {
  const tier = priorityOf(req)            // e.g. checkout = critical
  if (inFlight / capacity > LIMITS[tier]) {
    metrics.inc('shed', { tier })
    return res.status(503).set('Retry-After', '30').end()
  }
  inFlight++; res.on('finish', () => inFlight--)
  next()
})
